def market_embed() -> discord.Embed:
    """Builds the market/shop embed."""
    embed = discord.Embed(
        title="🛒 LASD Merit Points Market",
        description=(
            "Welcome to the LASD Market! Spend your Merit Points (MP) on exclusive perks and privileges.\n\n"
            "**How to Buy:** Click a button below to purchase an item. "
            "You'll be prompted to confirm your purchase.\n\n"
            f"**Your Balance:** Check with `/money-leaderboard` or the web panel."
        ),
        color=discord.Color.gold()
    )

    for item in MARKET_ITEMS:
        embed.add_field(
            name=f"{item['name']} — **${item['price']} MP**",
            value=item['description'],
            inline=False
        )

    embed.set_footer(text="Made by zeemonyt • LASD Utilities")
    return embed


